SVGS = ['<svg viewBox="0 0 700 240" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="240" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">NİSA SURESİ (1-101. AYETLER): KİMLİK VE TİLAVET İLKELERİ</text>\n  <rect x="20" y="45" width="320" height="175" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">SURENİN TEMEL ÖZELLİKLERİ</text>\n  <rect x="35" y="78" width="290" height="128" rx="6" fill="#ffffff" stroke="#3b82f6" stroke-width="1.2"/>\n  <text x="180" y="98" text-anchor="middle" font-size="10" fill="#334155">• Adı: en-Nisâ (Kadınlar) — Mushaf Sırası: 4</text>\n  <text x="180" y="118" text-anchor="middle" font-size="10" fill="#334155">• Nüzul Dönemi: Medine Dönemi (Uhud Savaşı sonrası)</text>\n  <text x="180" y="138" text-anchor="middle" font-size="10" fill="#334155">• Toplam Ayet: 176 (Bu bölümde: 1-101. ayetler / 18 sayfa)</text>\n  <text x="180" y="158" text-anchor="middle" font-size="10" fill="#334155">• Cüz Aralığı: 4. Cüzün sonu, 5. Cüzün tamamı ve 6. Cüz</text>\n  <text x="180" y="180" text-anchor="middle" font-size="10" font-weight="bold" fill="#1d4ed8">İlk Ayet: İnsanlığın tek nefisten yaratılışı ve Sıla-i Rahim</text>\n\n  <rect x="360" y="45" width="320" height="175" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">YÜZÜNDEN OKUMA (TİLAVET) ADABI</text>\n  <rect x="375" y="78" width="290" height="128" rx="6" fill="#ffffff" stroke="#4ade80" stroke-width="1.2"/>\n  <text x="520" y="98" text-anchor="middle" font-size="10" fill="#334155">• Mahreç: Peltek (ث، ذ، ظ) ve boğaz (ح، خ، ع) harfleri</text>\n  <text x="520" y="118" text-anchor="middle" font-size="10" fill="#334155">• Sıfat: Kalın (istilâ) ve ince (istifâl) harf ayrımı</text>\n  <text x="520" y="138" text-anchor="middle" font-size="10" fill="#334155">• Tertîl: Acele etmeden, tane tane ve tefekkürle okuma</text>\n  <text x="520" y="158" text-anchor="middle" font-size="10" fill="#334155">• Vakıf ve İbtidâ: Secâvend duraklarına tam uyum</text>\n  <text x="520" y="180" text-anchor="middle" font-size="10" font-weight="bold" fill="#15803d">Hedef: Hatasız, akıcı ve anlam bilinciyle tilavet</text>\n</svg>', '<svg viewBox="0 0 700 240" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="240" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">NİSA SURESİNDEN ÖRNEKLERLE TECVİT UYGULAMALARI</text>\n  <rect x="20" y="45" width="320" height="175" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">1. MED (UZATMA) KURALLARI</text>\n  <rect x="35" y="78" width="290" height="128" rx="6" fill="#ffffff" stroke="#f59e0b" stroke-width="1.2"/>\n  <text x="180" y="98" text-anchor="middle" font-size="10" font-weight="bold" fill="#b45309">• Medd-i Muttasıl (Aynı kelimede hemze):</text>\n  <text x="180" y="114" text-anchor="middle" font-size="9.5" fill="#334155">en-Nisâi (النِّسَاءِ) — es-Süfehâe (السُّفَهَاءَ) — 4 elif</text>\n  <text x="180" y="136" text-anchor="middle" font-size="10" font-weight="bold" fill="#b45309">• Medd-i Munfasıl (Ayrı kelimede hemze):</text>\n  <text x="180" y="152" text-anchor="middle" font-size="9.5" fill="#334155">Yâ eyyühe (يَا أَيُّهَا) — İnnâ evhaynâ — Caiz med</text>\n  <text x="180" y="174" text-anchor="middle" font-size="10" font-weight="bold" fill="#b45309">• Medd-i Ivaz (İki üstün üzerinde vakıf):</text>\n  <text x="180" y="190" text-anchor="middle" font-size="9.5" fill="#334155">Alîmen Hakîmen -&gt; Dururken: Alîmen Hakîmâ (1 elif)</text>\n\n  <rect x="360" y="45" width="320" height="175" rx="10" fill="#e0e7ff" stroke="#4f46e5" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#3730a3">2. TENVİN VE SÂKİN NÛN KURALLARI</text>\n  <rect x="375" y="78" width="290" height="128" rx="6" fill="#ffffff" stroke="#6366f1" stroke-width="1.2"/>\n  <text x="520" y="98" text-anchor="middle" font-size="10" font-weight="bold" fill="#4338ca">• İdgam-ı Meal-Ğunne (ي م ن و):</text>\n  <text x="520" y="114" text-anchor="middle" font-size="9.5" fill="#334155">min nefsin vâhidetin (مِنْ نَفْسٍ وَاحِدَةٍ)</text>\n  <text x="520" y="134" text-anchor="middle" font-size="10" font-weight="bold" fill="#4338ca">• İdgam-ı Bilâ-Ğunne (ل ر):</text>\n  <text x="520" y="150" text-anchor="middle" font-size="9.5" fill="#334155">Ğafûran Rahîmâ (غَفُورًا رَحِيمًا)</text>\n  <text x="520" y="170" text-anchor="middle" font-size="10" font-weight="bold" fill="#4338ca">• İzhar / İhfa / İklab:</text>\n  <text x="520" y="186" text-anchor="middle" font-size="9.5" fill="#334155">Alîmen Hakîmâ (İzhar) | Semîan Basîrâ (İklab)</text>\n</svg>', '<svg viewBox="0 0 700 220" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="220" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">NİSA SURESİ 1-101. AYETLERİN ANA MESAJLARI</text>\n  <rect x="20" y="48" width="155" height="152" rx="8" fill="#dbeafe" stroke="#2563eb" stroke-width="1.8"/>\n  <text x="97" y="70" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">1. YETİM VE AİLE</text>\n  <text x="97" y="94" text-anchor="middle" font-size="9.5" fill="#334155">• Yetim malı dokunulmazlığı</text>\n  <text x="97" y="114" text-anchor="middle" font-size="9.5" fill="#334155">• Kadınların mehir ve</text>\n  <text x="97" y="130" text-anchor="middle" font-size="9.5" fill="#334155">miras (ferâiz) hakkı</text>\n  <text x="97" y="150" text-anchor="middle" font-size="9.5" fill="#334155">• Aile içi hakemlik (35)</text>\n\n  <rect x="190" y="48" width="155" height="152" rx="8" fill="#dcfce7" stroke="#16a34a" stroke-width="1.8"/>\n  <text x="267" y="70" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">2. TEVHİD VE İHSAN</text>\n  <text x="267" y="94" text-anchor="middle" font-size="9.5" fill="#334155">• Şirkten sakınma (36, 48)</text>\n  <text x="267" y="114" text-anchor="middle" font-size="9.5" fill="#334155">• Anne-babaya iyilik</text>\n  <text x="267" y="134" text-anchor="middle" font-size="9.5" fill="#334155">• Yakın ve uzak komşu</text>\n  <text x="267" y="154" text-anchor="middle" font-size="9.5" fill="#334155">• Kibir ve riyadan uzaklık</text>\n\n  <rect x="360" y="48" width="155" height="152" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="1.8"/>\n  <text x="437" y="70" text-anchor="middle" font-size="11" font-weight="bold" fill="#92400e">3. EMANET &amp; ADALET</text>\n  <text x="437" y="94" text-anchor="middle" font-size="9.5" fill="#334155">• Emaneti ehline verme (58)</text>\n  <text x="437" y="114" text-anchor="middle" font-size="9.5" fill="#334155">• Adaletle hükmetme</text>\n  <text x="437" y="134" text-anchor="middle" font-size="9.5" fill="#334155">• Karşılıklı rıza ile</text>\n  <text x="437" y="150" text-anchor="middle" font-size="9.5" fill="#334155">helal ticaret (29)</text>\n\n  <rect x="530" y="48" width="150" height="152" rx="8" fill="#fae8ff" stroke="#9333ea" stroke-width="1.8"/>\n  <text x="605" y="70" text-anchor="middle" font-size="11" font-weight="bold" fill="#6b21a8">4. BARIŞ &amp; HUKUK</text>\n  <text x="605" y="94" text-anchor="middle" font-size="9.5" fill="#334155">• Selama en güzel karşılık (86)</text>\n  <text x="605" y="114" text-anchor="middle" font-size="9.5" fill="#334155">• Can dokunulmazlığı (93)</text>\n  <text x="605" y="134" text-anchor="middle" font-size="9.5" fill="#334155">• Yolculukta namazları</text>\n  <text x="605" y="150" text-anchor="middle" font-size="9.5" fill="#334155">kısaltma (Kasr - 101)</text>\n</svg>']

